use bennett_isa_ref::{Object,ClassicalMachine};
fn main(){let p=std::env::args().nth(1).unwrap();let o=Object::parse(&std::fs::read_to_string(p).unwrap()).unwrap();o.check_hashes().unwrap();println!("parse/check_hashes: ok");let mut m=ClassicalMachine::new(&o,"f",&[],&[]).unwrap();let entry=m.snapshot();m.step_once().unwrap();m.step_once().unwrap();let prefix=m.snapshot();println!("two instructions complete; sparse allocation legal");match m.step_once(){Ok(_)=>println!("HOST_REQUEST payload length {}",m.outcome().request.unwrap().payload.len()),Err(e)=>{println!("reported error: {e}");assert!(e.to_string().contains("§10")&&e.to_string().contains("host limit"));assert_eq!(m.snapshot(),prefix);assert!(m.host_transcript().is_empty());assert!(m.console().is_empty());assert_eq!(m.effect_tape_len(),0);m.reverse().unwrap();assert_eq!(m.snapshot(),entry);println!("rejection unchanged; reversal restored entry");}}}